const calYmdToUTC = (s) => { const p = calYmdParts(s); return p ? Date.UTC(p.y, p.m - 1, p.d) : NaN; };
// ---- site ----
const calUTCToYmd = (ms) => {
  const d = new Date(ms);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
};
// ---- site ----
const calAddDays = (s, n) => { const t = calYmdToUTC(s); return Number.isNaN(t) ? null : calUTCToYmd(t + n * 86400000); };
// ---- site ----
