const seriesPricedOn = (rows, field, asOf) => {
  if(!asOf) return true;
  for(let i = (rows || []).length - 1; i >= 0; i--){
    if(rows[i] && rows[i][field] != null) return String(rows[i].date).slice(0, 10) >= asOf;
  }
  return false;
};
