const PRICE_STANDING_WINDOWS = [
  {days: 365, adj: "12-month", noun: "12 months"},
  {days: 180, adj: "6-month",  noun: "6 months"},
  {days: 90,  adj: "3-month",  noun: "3 months"},
];
// ---- site ----
const PRICE_STANDING_MIN_POINTS = 30;
// ---- site ----
const PRICE_STANDING_MIN_SPAN_RATIO = 0.8;
// ---- site ----
const PRICE_STANDING_MIN_SPREAD = 1.15;
// ---- site ----
const PRICE_STANDING_LOW = 0.10;
// ---- site ----
const PRICE_STANDING_NEAR_LOW = 0.25;
// ---- site ----
const PRICE_STANDING_HIGH = 0.90;
// ---- site ----
function priceStanding(rows, opts){
  const field = (opts && opts.field) || "market_price";
  const DAY = 86400000;
  const pts = (rows || [])
    .map(r => ({t: Date.parse(r.date), v: r[field] != null ? parseFloat(r[field]) : null}))
    .filter(p => Number.isFinite(p.t) && Number.isFinite(p.v) && p.v > 0);
  if(pts.length < PRICE_STANDING_MIN_POINTS) return null;
  const last = pts[pts.length - 1];
  for(const w of PRICE_STANDING_WINDOWS){
    const cutoff = last.t - w.days * DAY;
    const inWin = pts.filter(p => p.t >= cutoff);
    if(inWin.length < PRICE_STANDING_MIN_POINTS) continue;
    const span = (inWin[inWin.length - 1].t - inWin[0].t) / DAY;
    if(span < w.days * PRICE_STANDING_MIN_SPAN_RATIO) continue;
    let lo = Infinity, hi = 0;
    for(const p of inWin){ if(p.v < lo) lo = p.v; if(p.v > hi) hi = p.v; }
    if(!(lo > 0) || hi / lo < PRICE_STANDING_MIN_SPREAD) continue;
    // Fraction of the window priced at or below today, TIES INCLUDED. That is
    // deliberate: a card that has sat at $5 for half the year and is at $5
    // today is not at a special low, and counting ties keeps it out of the
    // bottom decile. The cost is that a flat series lands at 1.0, which the
    // spread floor above is what catches.
    const atOrBelow = inWin.reduce((n, p) => n + (p.v <= last.v ? 1 : 0), 0);
    const pct = atOrBelow / inWin.length;
    let tone = null, label = null;
    if(pct <= PRICE_STANDING_LOW){ tone = "low"; label = "Cheapest in " + w.noun; }
    else if(pct <= PRICE_STANDING_NEAR_LOW){ tone = "near-low"; label = "Near its " + w.adj + " low"; }
    else if(pct >= PRICE_STANDING_HIGH){ tone = "high"; label = "Near its " + w.adj + " high"; }
    if(!tone) return null;
    return {tone, label, window: w.adj, pct, n: inWin.length, value: last.v};
  }
  return null;
}
