// ---- site ----
function amazonForSealed(product, setName){
  if(!product) return null;
  const clean = cleanSealedName(product.name || "");
  if(!clean) return null;
  const norm = _amznNorm(clean);
  const type = deriveSealedDisplayType(product);
  // A case or display (six boxes, a tray of starter sets) is not the single
  // product a rule's ASIN points at — it gets a search, never that listing.
  const bulk = type === "Cases" || type === "Other Displays / Cases";
  if(!bulk) for(const rule of AMAZON_SEALED_RULES){
    if(rule.tokens.every(t => norm.includes(t))) return {url: amazonUrl(rule.asin), exact: true};
  }
  if(product.is_puzzle){
    const asin = AMAZON_PUZZLE_ASINS[(product.tcgplayer_product_id || 0) - 900000000];
    if(asin) return {url: amazonUrl(asin), exact: true};
  }
  const byType = AMAZON_ASIN_BY_SET[type];
  const asin = byType && setName ? byType[setName] : null;
  if(asin) return {url: amazonUrl(asin), exact: true};
  // The set name is prepended because a bare "Booster Pack Display" search is
  // every set at once — and dropped again when the name already carries it,
  // since "Azurite Sea Azurite Sea Booster Box" narrows a search to nothing.
  const q = setName && !norm.includes(_amznNorm(setName))
    ? `Disney Lorcana ${setName} ${clean}`
    : `Disney Lorcana ${clean}`;
  return {url: amazonSearchUrl(q), exact: false};
}
